import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Werte referenzieren","description":"Womit ein ApptiveScript-Ausdruck anfängt — Feldwerte, Formulareingaben, Schrittergebnisse.","frontmatter":{"title":"Werte referenzieren","description":"Womit ein ApptiveScript-Ausdruck anfängt — Feldwerte, Formulareingaben, Schrittergebnisse."},"headers":[],"relativePath":"apptivescript/werte-referenzieren.md","filePath":"apptivescript/werte-referenzieren.md","lastUpdated":1786434193000}'),a={name:"apptivescript/werte-referenzieren.md"};function d(s,e,l,o,c,h){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="werte-referenzieren" tabindex="-1">Werte referenzieren <a class="header-anchor" href="#werte-referenzieren" aria-label="Permalink to &quot;Werte referenzieren&quot;">​</a></h1><p>Die Schreibweise ist überall dieselbe. Unterschiedlich ist der <strong>Einstieg</strong> — also der erste Wert, mit dem ein Ausdruck beginnt. Er hängt davon ab, an welcher Stelle Sie schreiben.</p><table tabindex="0"><thead><tr><th>Einstieg</th><th>Steht für</th><th>Verfügbar in</th></tr></thead><tbody><tr><td><code>fieldValue(&#39;&lt;Feld-Id&gt;&#39;)</code></td><td>ein Feld des aktuellen Eintrags</td><td>Formelspalten, Filter</td></tr><tr><td><code>formValues.get(&#39;&lt;Key&gt;&#39;)</code></td><td>eine Eingabe auf einer Seite</td><td>bedingte Sichtbarkeit</td></tr><tr><td><code>step(&#39;&lt;Schritt-Id&gt;&#39;)</code></td><td>ein früherer Schritt eines Flows</td><td>Flows</td></tr><tr><td><code>today()</code> · <code>now()</code></td><td>heutiges Datum · aktueller Zeitpunkt</td><td>überall</td></tr><tr><td><code>true</code> · <code>false</code></td><td>feste Wahrheitswerte</td><td>überall</td></tr><tr><td><code>loggedInUser()</code></td><td>die angemeldete Person</td><td>überall</td></tr><tr><td><code>owner</code></td><td>Eigentümer des Space</td><td>Flows</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Der häufigste Fehler steht in dieser Tabelle</p><p>Ein Einstieg, den es an dieser Stelle nicht gibt, führt <strong>nicht</strong> zu einer Fehlermeldung, sondern zu einem leeren Ergebnis. <code>fieldValue(&#39;…&#39;)</code> in einer Sichtbarkeitsregel bleibt also stumm wirkungslos, und der Block verschwindet dauerhaft. Prüfen Sie zuerst den Einstieg, dann die Funktion.</p></div><h2 id="felder-eines-eintrags-fieldvalue" tabindex="-1">Felder eines Eintrags: <code>fieldValue</code> <a class="header-anchor" href="#felder-eines-eintrags-fieldvalue" aria-label="Permalink to &quot;Felder eines Eintrags: `fieldValue`&quot;">​</a></h2><p>In einer <strong>Formelspalte</strong> und in <strong>Filtern</strong> greifen Sie auf die anderen Felder desselben Eintrags zu:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;64f2a1c0b53ff00c6bdf1234&#39;).multiplyBy(1.19)</span></span></code></pre></div><p>Der Wert in den Klammern ist die <strong>Id</strong> der Spalte, nicht ihr Name.</p><div class="tip custom-block"><p class="custom-block-title">Nie tippen, immer einfügen</p><p>Im Formeleditor listet der Reiter <strong>Search</strong> alle verwendbaren Felder mit ihrem Namen auf. Ein Klick fügt <code>fieldValue(&#39;…&#39;)</code> mit der richtigen Id ein und zeigt es als farbigen Baustein mit dem Feldnamen an. Damit sehen Sie im Ausdruck den Namen, gespeichert wird die Id.</p></div><p>Dass die Id gespeichert wird, hat einen Vorteil: <strong>eine Formel überlebt das Umbenennen der Spalte.</strong> Und einen Nachteil: Wird die Spalte gelöscht, meldet der Editor <em>No field with id …</em> — der Feldname steht dann nicht mehr im Ausdruck.</p><p><strong>Welche Felder verwendbar sind:</strong> Text, Zahl, Kommazahl, Währung, Datum, Datum und Uhrzeit, Erstellt am, Häkchen, Benutzer, E-Mail und Geolokalisierung. Andere Spaltentypen tauchen im Picker nicht auf.</p><div class="warning custom-block"><p class="custom-block-title">Formelspalten verweisen nicht auf Formelspalten</p><p>Felder vom Typ <em>Formel</em> werden im Picker ausgelassen — sonst könnte eine Formel sich selbst berechnen wollen. Wenn Sie auf einem berechneten Wert aufbauen müssen, wiederholen Sie die Rechnung im neuen Ausdruck.</p></div><h2 id="eingaben-einer-seite-formvalues" tabindex="-1">Eingaben einer Seite: <code>formValues</code> <a class="header-anchor" href="#eingaben-einer-seite-formvalues" aria-label="Permalink to &quot;Eingaben einer Seite: `formValues`&quot;">​</a></h2><p>In der <a href="/seiten/sichtbarkeit">bedingten Sichtbarkeit</a> eines Blocks kommen die Werte aus den Eingabeblöcken derselben Seite:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;alter&#39;).greaterThan(17)</span></span></code></pre></div><p>Der Zugriff erfolgt über den <strong>Key</strong> des Eingabeblocks — nicht über seine Beschriftung. Alle Keys einer Seite sehen Sie über <strong>Keys verwalten</strong>. → <a href="/seiten/eingabebloecke">Eingabeblöcke</a></p><div class="danger custom-block"><p class="custom-block-title">Ein falscher Key blendet dauerhaft aus</p><p>Heißt der Key <code>age</code> und die Regel fragt <code>formValues.get(&#39;alter&#39;)</code>, dann ist die Bedingung <strong>immer falsch</strong> — der Block erscheint nie, ohne jede Meldung. Dasselbe passiert, wenn der Key nachträglich geändert wird.</p><p>Legen Sie sprechende Keys fest, <strong>bevor</strong> Sie Bedingungen darauf bauen.</p></div><p>Ein Sonderfall mit umgekehrtem Ausgang: Ist der Ausdruck nicht nur ins Leere gerichtet, sondern <strong>syntaktisch falsch</strong>, bleibt der Block sichtbar. Ein Block, der immer erscheint, deutet also auf einen Schreibfehler; ein Block, der nie erscheint, auf einen falschen Key.</p><h2 id="ergebnisse-fruherer-schritte-step" tabindex="-1">Ergebnisse früherer Schritte: <code>step</code> <a class="header-anchor" href="#ergebnisse-fruherer-schritte-step" aria-label="Permalink to &quot;Ergebnisse früherer Schritte: `step`&quot;">​</a></h2><p>In einem <a href="/flows/was-ist-ein-flow">Flow</a> liefert jeder Schritt ein Ergebnis, auf das die folgenden zugreifen können:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>step(&#39;66f13d06b53ff00c6bdf2769&#39;).output.get(&#39;email&#39;)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Teil</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>step(&#39;…&#39;)</code></td><td>der Schritt, erkannt an seiner Id</td></tr><tr><td><code>.output</code></td><td>das Ergebnis dieses Schritts</td></tr><tr><td><code>.get(&#39;…&#39;)</code></td><td>ein einzelnes Feld daraus</td></tr></tbody></table><p>Auch hier tippt niemand Ids: Der Reiter <strong>Flow</strong> im Ausdruckseditor zeigt die Schritte des Flows als Baum, und ein Klick fügt den passenden Ausdruck ein. Der Baum entsteht aus dem <strong>letzten Testlauf</strong> — ohne Testlauf ist er leer, und der Editor sagt das auch:</p><blockquote><p><em>Zuerst musst du den Flow testen</em></p></blockquote><p>→ <a href="/flows/testen">Flows testen</a> · <a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></p><div class="tip custom-block"><p class="custom-block-title">Verschachtelte Daten mit mehreren <code>get</code></p><p>Webhook-Daten und JSON-Antworten sind oft verschachtelt. Dann hängen Sie <code>get()</code> mehrfach aneinander: <code>step(&#39;…&#39;).output.get(&#39;kunde&#39;).get(&#39;email&#39;)</code>. Jedes <code>get()</code> geht eine Ebene tiefer.</p></div><h2 id="datum-person-space" tabindex="-1">Datum, Person, Space <a class="header-anchor" href="#datum-person-space" aria-label="Permalink to &quot;Datum, Person, Space&quot;">​</a></h2><p>Diese Einstiege brauchen keinen Bezug zu einem Eintrag oder Schritt:</p><table tabindex="0"><thead><tr><th>Ausdruck</th><th>Ergebnis</th></tr></thead><tbody><tr><td><code>today()</code></td><td>das heutige Datum, ohne Uhrzeit</td></tr><tr><td><code>now()</code></td><td>der aktuelle Zeitpunkt mit Uhrzeit</td></tr><tr><td><code>loggedInUser()</code></td><td>die angemeldete Person, mit <code>.email</code>, <code>.firstName</code>, <code>.lastName</code>, <code>.id</code></td></tr><tr><td><code>owner</code></td><td>der Eigentümer des Space, mit <code>.email</code>, <code>.firstName</code>, <code>.lastName</code></td></tr><tr><td><code>true</code> · <code>false</code></td><td>feste Wahrheitswerte</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;frist&#39;).before(today())</span></span>\n<span class="line"><span>loggedInUser().email.isEqualTo(fieldValue(&#39;bearbeiter&#39;))</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title"><code>owner</code> bietet die Oberfläche nur in Flows an</p><p>Die drei Werte <em>E-Mail Space Eigentümer</em>, <em>Vorname Space Eigentümer</em> und <em>Nachname Space Eigentümer</em> stehen im Ausdruckseditor als <strong>Flow-Variablen</strong> zur Auswahl. Für Formeln und Sichtbarkeitsregeln bietet die Oberfläche sie nicht an — verlassen Sie sich dort nicht darauf.</p></div><div class="tip custom-block"><p class="custom-block-title">Wer ist bei einem Flow angemeldet?</p><p><code>loggedInUser()</code> ist die Person, die die Aktion ausgelöst hat. Läuft ein Flow über einen <a href="/flows/webhook-trigger">Webhook</a> oder ein öffentliches Formular, ist das nicht zwangsläufig ein Mitglied des Space. Für Zuordnungen ist ein ausdrücklich gefülltes Feld verlässlicher als der angemeldete Benutzer.</p></div><h2 id="welcher-typ-kommt-heraus" tabindex="-1">Welcher Typ kommt heraus <a class="header-anchor" href="#welcher-typ-kommt-heraus" aria-label="Permalink to &quot;Welcher Typ kommt heraus&quot;">​</a></h2><p>In einer <strong>Formelspalte</strong> wählen Sie unter <em>Ergebnis anzeigen als</em> den Spaltentyp des Ergebnisses. Die Auswahl richtet sich nach dem Typ, den der Ausdruck liefert:</p><table tabindex="0"><thead><tr><th>Ausdruck ergibt</th><th>wählbare Spaltentypen</th></tr></thead><tbody><tr><td>Wahrheitswert</td><td>Häkchen</td></tr><tr><td>Zahl</td><td>Zahl, Kommazahl, Währung</td></tr><tr><td>Kommazahl</td><td>Kommazahl, Währung</td></tr><tr><td>Text</td><td>Text</td></tr><tr><td>Datum</td><td>Datum</td></tr><tr><td>Datum und Uhrzeit</td><td>Datum und Uhrzeit</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Warum die Auswahl manchmal auf einen Eintrag zusammenschrumpft</p><p>Bleibt nur ein Spaltentyp übrig, setzt ihn der Editor selbst — der Ausdruck lässt keinen anderen zu. Umgekehrt heißt eine plötzlich lange Liste: Der Ausdruck ist noch nicht auswertbar, und der Typ steht noch nicht fest.</p></div><p>Welchen Typ ein Ausdruck gerade liefert, steht im Editor über dem Beispielergebnis — <em>Typ: String</em>, <em>Typ: Number</em>. Er entscheidet auch darüber, welche Funktionen als Nächstes möglich sind. → <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a></p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptivescript/schreibweise">Schreibweise</a> — Punkt, Klammern, Anführungszeichen</li><li><a href="/apptivescript/bedingungen">Bedingungen bauen</a> — Vergleiche, UND/ODER, Verzweigungen</li><li><a href="/apptivescript/editor">Der Ausdruckseditor</a> — Token-Ansicht, Picker, Beispielergebnis</li><li><a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a> — alle Funktionen je Typ</li><li><a href="/grids/berechnete-felder">Berechnete Felder</a> · <a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a> · <a href="/seiten/eingabebloecke">Eingabeblöcke</a></li></ul>',39)])])}const g=t(a,[["render",d]]);export{p as __pageData,g as default};
